// function pointer named mc_gl<Name>, and a macro maps the plain GL name onto it.
// The pointers are resolved through the windowing layer, so libGL is never linked.
// <GL/glcorearb.h> supplies only types, enums and PFN typedefs, because
// GL_GLEXT_PROTOTYPES is never defined. Code that includes this header must build
// with GLFW_INCLUDE_NONE.
