namespace mc::gl {

// Matches GLFWglproc, so glfwGetProcAddress can be passed directly.
using Proc = void (*)(void);
using LoaderFunc = Proc (*)(const char* name);

// Resolves every entry point above. Returns false (and logs the missing names) if
// the current context is not OpenGL 4.5 core.
bool load(LoaderFunc loader);
bool isLoaded();
bool hasExtension(const char* name);

// Routes KHR_debug messages to the log. Call this only on a context created with the
// debug flag.
void enableDebugOutput();

} // namespace mc::gl
